"""A2A event queue manager helpers."""

from __future__ import annotations

import asyncio

import structlog
from a2a.server.events import EventQueue, InMemoryQueueManager
from a2a.server.events.queue_manager import NoTaskQueue

structlogger = structlog.get_logger()


class TrackingInMemoryQueueManager(InMemoryQueueManager):
    """In-memory queue manager that records task IDs through public APIs."""

    def __init__(self) -> None:
        super().__init__()
        self._tracked_task_ids: set[str] = set()
        self._tracked_lock = asyncio.Lock()

    async def _track(self, task_id: str) -> None:
        async with self._tracked_lock:
            self._tracked_task_ids.add(task_id)

    async def _untrack(self, task_id: str) -> None:
        async with self._tracked_lock:
            self._tracked_task_ids.discard(task_id)

    async def add(self, task_id: str, queue: EventQueue) -> None:
        await super().add(task_id, queue)
        await self._track(task_id)

    async def create_or_tap(self, task_id: str) -> EventQueue:
        queue = await super().create_or_tap(task_id)
        await self._track(task_id)
        return queue

    async def close(self, task_id: str) -> None:
        try:
            await super().close(task_id)
        finally:
            await self._untrack(task_id)

    async def close_all(self) -> None:
        async with self._tracked_lock:
            task_ids = list(self._tracked_task_ids)

        for task_id in task_ids:
            try:
                await self.close(task_id)
            except NoTaskQueue:
                await self._untrack(task_id)
            except Exception:
                structlogger.warning(
                    "a2a_server.queue_manager.close_failed",
                    task_id=task_id,
                    exc_info=True,
                )
